def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    op_def = 0
    my_def = 0
    for i in range(n):
        if op[i] == 'D':
            op_def += 1
        if my[i] == 'D':
            my_def += 1
    op_coop = n - op_def
    last_my = my[-1]
    last_op = op[-1]

    # Endgame: last 5 rounds. If opponent is very cooperative, exploit hard.
    if n >= 95:
        if op_def <= n // 4:
            return 'D'
        if op_def * 2 >= n:
            return 'D'
        return 'D'

    # Against a sustained defector, never cooperate.
    if n >= 6:
        recent_op = op[-6:]
        rdef = 0
        for a in recent_op:
            if a == 'D':
                rdef += 1
        if rdef >= 5:
            return 'D'

    # Detect mostly-cooperative opponents early: cooperate.
    if n < 8:
        if op_def == 0:
            return 'C'
        if last_op == 'D':
            return 'D'
        return 'C'

    # If opponent rarely defects (<=1 in whole match so far), treat as cooperative.
    if op_def <= 1:
        # Occasionally probe for exploit, mostly cooperate.
        if n >= 15 and n % 12 == 0:
            return 'D'
        return 'C'

    # Forgiveness: if opponent defected after a long cooperative stretch,
    # punish once then return to cooperation. This helps recover from noise
    # and from TFT-style retaliation cycles.
    if last_op == 'D':
        # Count consecutive trailing opponent defections.
        trail = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                trail += 1
            else:
                break
        # Count consecutive trailing own defections.
        mytrail = 0
        for i in range(n - 1, -1, -1):
            if my[i] == 'D':
                mytrail += 1
            else:
                break

        if trail >= 3:
            return 'D'

        # If we're already in a mutual retaliation cycle, break it.
        if mytrail >= 2 and trail <= 2:
            return 'C'

        # Single defection: retaliate once.
        if trail == 1:
            return 'D'

        return 'D'

    # Opponent cooperated last round.
    # If we've been defecting too much relative to opponent cooperation, return to C.
    if last_my == 'D' and my_def > op_def + 2:
        return 'C'

    # Exploit a very cooperative opponent occasionally, but not too often,
    # to keep them cooperating.
    if op_def * 5 <= n:
        # Very cooperative opponent. Probe rarely.
        if n >= 20 and n % 10 == 0:
            return 'D'
        return 'C'

    # Moderately cooperative: mostly cooperate with rare probes.
    if op_def * 3 <= n:
        if n >= 25 and n % 15 == 0:
            return 'D'
        return 'C'

    # Opponent defects fairly often but not overwhelmingly.
    # Be cautious, cooperate only if recent behavior is good.
    recent = op[-4:]
    rc = 0
    for a in recent:
        if a == 'C':
            rc += 1
    if rc >= 3:
        return 'C'
    if rc <= 1:
        return 'D'
    if last_my == 'D':
        return 'C'
    return 'D'
